import { readdirSync, readFileSync, statSync } from 'node:fs';
import { join, relative, sep } from 'node:path';
import { describe, expect, it } from 'vitest';

/**
 * Structural guard for the Tasks beta gate.
 *
 * The gate only holds if EVERY surface outside the feature reads it. A unit test
 * cannot catch the failure that matters here — someone adds a sixth entry point
 * (a mobile nav row, a search result, a menu item), forgets the atom, and that
 * one door stays open for users who never enabled the beta. Nothing else fails:
 * the feature works, the tests pass, and the leak is invisible until a user
 * reports seeing a feature that should not exist.
 *
 * So this asserts the rule directly against the source tree: a file outside the
 * Tasks feature that reaches into Tasks code must also read
 * `tasksFeatureEnabledAtom` (or, for the two routes, mount the guard that does).
 *
 * If this fails on a file you just added, wire the gate rather than widening the
 * exemptions — the exemptions are for code that only ever runs INSIDE an
 * already-gated surface.
 */

const SRC = join(__dirname, '..', 'src');
const GATE_ATOM = 'tasksFeatureEnabledAtom';
const ROUTE_GUARD = 'TasksBetaRouteGuard';

/** Imports that mean "this file reaches into the Tasks feature". */
const TASK_IMPORT_PATTERNS = [
  /from\s+['"][^'"]*atoms\/tasks['"]/,
  /from\s+['"][^'"]*components\/tasks\//,
  /from\s+['"][^'"]*hooks\/use-task-/,
];

/**
 * Interior of the feature: these only ever render or run beneath a surface that
 * is already gated, so re-checking the atom inside them would be noise.
 */
function isFeatureInterior(relPath: string): boolean {
  const p = relPath.split(sep).join('/');
  return (
    p.startsWith('components/tasks/') ||
    p.startsWith('hooks/use-task-') ||
    p === 'atoms/tasks.ts' ||
    p.startsWith('stories/') ||
    // Generated by the router; carries no logic of its own.
    p === 'routeTree.gen.ts'
  );
}

/**
 * Type-only imports vanish at runtime, so they cannot put a surface on screen —
 * a helper that borrows a Task type is not an entry point. Drop them before
 * deciding whether a file reaches into the feature.
 */
function withoutTypeOnlyImports(source: string): string {
  return source.replace(/import\s+type\s+[\s\S]*?from\s+['"][^'"]+['"];?/g, '');
}

function walk(dir: string, out: string[] = []): string[] {
  for (const entry of readdirSync(dir)) {
    const full = join(dir, entry);
    if (statSync(full).isDirectory()) {
      walk(full, out);
    } else if (/\.(ts|tsx)$/.test(entry)) {
      out.push(full);
    }
  }
  return out;
}

describe('Tasks beta gate coverage', () => {
  const files = walk(SRC).map((full) => ({
    rel: relative(SRC, full).split(sep).join('/'),
    source: readFileSync(full, 'utf8'),
  }));

  const reachesIntoTasks = files.filter((f) => {
    if (isFeatureInterior(f.rel)) return false;
    const runtimeImports = withoutTypeOnlyImports(f.source);
    return TASK_IMPORT_PATTERNS.some((re) => re.test(runtimeImports));
  });

  it('finds the known entry points (guards against the scan silently matching nothing)', () => {
    // If this list shrinks to zero the assertions below become vacuous, so the
    // scan itself is checked before it is trusted.
    expect(reachesIntoTasks.length).toBeGreaterThanOrEqual(5);
  });

  it('gates every surface outside the Tasks feature', () => {
    const ungated = reachesIntoTasks
      .filter((f) => !f.source.includes(GATE_ATOM) && !f.source.includes(ROUTE_GUARD))
      .map((f) => f.rel);

    expect(
      ungated,
      `These files reach into Tasks without reading ${GATE_ATOM}. Wire the gate — ` +
        `an entry point that skips it stays visible to users who never enabled the beta.`
    ).toEqual([]);
  });

  it('guards both Tasks routes, so a direct URL cannot reach the feature', () => {
    const routes = files.filter((f) => /^routes\/.*\/tasks\.[^/]+\.tsx$/.test(f.rel));
    expect(routes.map((f) => f.rel).sort()).toEqual([
      'routes/$workspaceName/_auth/tasks.$taskId.tsx',
      'routes/$workspaceName/_auth/tasks.index.tsx',
    ]);
    for (const route of routes) {
      expect(route.source, `${route.rel} must mount ${ROUTE_GUARD}`).toContain(ROUTE_GUARD);
    }
  });

  it('keeps the Tasks commands out of the always-registered placeholder list', () => {
    // Placeholders exist so shortcuts list even where a command is not mounted;
    // for Tasks that would advertise the feature to users who cannot use it.
    const builtIns = files.find((f) => f.rel === 'lib/commands/built-ins.ts');
    expect(builtIns).toBeDefined();
    const list = builtIns?.source.match(
      /const UNAVAILABLE_COMMANDS[\s\S]*?\n\];/
    )?.[0];
    expect(list).toBeDefined();
    expect(list).not.toContain("id: 'tasks.");
  });
});
